import{_ as e,o as i,c as o,a2 as r}from"./chunks/framework.CgxQ0r6v.js";const g=JSON.parse('{"title":"Planificación Académica: Proyecto Sociotecnológico IV (Trimestre X)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_IV/Planificacion_Trimestre_IV-X.md","filePath":"materias/Proyecto_Sociotecnologico_IV/Planificacion_Trimestre_IV-X.md"}'),t={name:"materias/Proyecto_Sociotecnologico_IV/Planificacion_Trimestre_IV-X.md"};function d(n,a,c,s,l,u){return i(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="planificacion-academica-proyecto-sociotecnologico-iv-trimestre-x" tabindex="-1">Planificación Académica: Proyecto Sociotecnológico IV (Trimestre X) <a class="header-anchor" href="#planificacion-academica-proyecto-sociotecnologico-iv-trimestre-x" aria-label="Permalink to &quot;Planificación Académica: Proyecto Sociotecnológico IV (Trimestre X)&quot;">​</a></h1><p>El Proyecto Sociotecnológico IV (PST IV) constituye el Trabajo Especial de Grado para optar al título de <strong>Ingeniero/a en Informática</strong> en la Universidad Politécnica Territorial del Estado Trujillo &quot;Mario Briceño Iragorry&quot;. En este nivel, los proyectos trascienden la simple automatización de formularios, abordando soluciones integrales de alta complejidad técnica: integración hardware-software, seguridad informática, análisis masivo de datos, arquitecturas cloud/distribuidas y gestión rigurosa de calidad.</p><hr><h2 id="📅-trimestre-x-diagnostico-de-alto-nivel-gestion-de-calidad-y-formulacion-de-la-propuesta-unidades-1-2-y-3" tabindex="-1">📅 Trimestre X: Diagnóstico de Alto Nivel, Gestión de Calidad y Formulación de la Propuesta (Unidades 1, 2 y 3) <a class="header-anchor" href="#📅-trimestre-x-diagnostico-de-alto-nivel-gestion-de-calidad-y-formulacion-de-la-propuesta-unidades-1-2-y-3" aria-label="Permalink to &quot;📅 Trimestre X: Diagnóstico de Alto Nivel, Gestión de Calidad y Formulación de la Propuesta (Unidades 1, 2 y 3)&quot;">​</a></h2><h3 id="📝-evaluacion-1-diagnostico-organizacional-y-articulacion-hardware-software-unidad-1" tabindex="-1">📝 Evaluación 1: Diagnóstico Organizacional y Articulación Hardware/Software (Unidad 1) <a class="header-anchor" href="#📝-evaluacion-1-diagnostico-organizacional-y-articulacion-hardware-software-unidad-1" aria-label="Permalink to &quot;📝 Evaluación 1: Diagnóstico Organizacional y Articulación Hardware/Software (Unidad 1)&quot;">​</a></h3><p><strong>Objetivo:</strong> Realizar el diagnóstico integral identificando requerimientos complejos en áreas de infraestructura de hardware, redes y software.</p><ul><li>Abordaje a organizaciones estratégicas (complejos industriales, instituciones de salud de tercer nivel, telecomunicaciones, ministerios).</li><li>Cuantificación rigurosa de datos y flujos de información críticos.</li><li>Planificación y organización por áreas de saberes: requerimientos de hardware, conectividad y arquitectura de software.</li><li><strong>Actividad:</strong> <strong>Informe de Diagnóstico Estratégico y ERS Avanzada.</strong> (25%)</li></ul><h3 id="📝-evaluacion-2-administracion-y-metricas-de-calidad-del-proyecto-unidad-2" tabindex="-1">📝 Evaluación 2: Administración y Métricas de Calidad del Proyecto (Unidad 2) <a class="header-anchor" href="#📝-evaluacion-2-administracion-y-metricas-de-calidad-del-proyecto-unidad-2" aria-label="Permalink to &quot;📝 Evaluación 2: Administración y Métricas de Calidad del Proyecto (Unidad 2)&quot;">​</a></h3><p><strong>Objetivo:</strong> Establecer los factores, estándares y métricas de calidad que regirán el ciclo de vida del proyecto.</p><ul><li>Modelos y estándares internacionales de calidad de software (ISO/IEC 25010 / SQuaRE, CMMI).</li><li>Factores y métricas de calidad según el área: fiabilidad, mantenibilidad, portabilidad, seguridad y usabilidad.</li><li>Plan de Gestión de la Calidad del Software (QA Plan).</li><li><strong>Actividad:</strong> <strong>Documento del Plan de Calidad y Métricas del Proyecto.</strong> (25%)</li></ul><h3 id="📝-evaluacion-3-estimaciones-de-la-propuesta-y-estudio-de-factibilidad-unidad-3" tabindex="-1">📝 Evaluación 3: Estimaciones de la Propuesta y Estudio de Factibilidad (Unidad 3) <a class="header-anchor" href="#📝-evaluacion-3-estimaciones-de-la-propuesta-y-estudio-de-factibilidad-unidad-3" aria-label="Permalink to &quot;📝 Evaluación 3: Estimaciones de la Propuesta y Estudio de Factibilidad (Unidad 3)&quot;">​</a></h3><p><strong>Objetivo:</strong> Estimar con precisión científica los recursos, riesgos, tiempos, esfuerzo e impacto del proyecto.</p><ul><li>Modelos de estimación de esfuerzo y costos de software (Puntos de Función, Puntos de Caso de Uso, COCOMO II).</li><li>Matriz de Gestión de Riesgos Avanzada (técnicos, de infraestructura, humanos y regulatorios).</li><li>Estudio de Factibilidad Multidimensional: Técnica, Operativa, Económica y Legal bajo la Soberanía Tecnológica.</li><li><strong>Actividad:</strong> <strong>Estudio de Factibilidad y Modelo de Estimación de Esfuerzo.</strong> (25%)</li></ul><h3 id="📝-evaluacion-4-elaboracion-y-presentacion-de-la-propuesta-del-proyecto-unidades-1-a-3" tabindex="-1">📝 Evaluación 4: Elaboración y Presentación de la Propuesta del Proyecto (Unidades 1 a 3) <a class="header-anchor" href="#📝-evaluacion-4-elaboracion-y-presentacion-de-la-propuesta-del-proyecto-unidades-1-a-3" aria-label="Permalink to &quot;📝 Evaluación 4: Elaboración y Presentación de la Propuesta del Proyecto (Unidades 1 a 3)&quot;">​</a></h3><p><strong>Objetivo:</strong> Formalizar y defender la propuesta integral de ingeniería ante el comité académico de proyectos.</p><ul><li>Elaboración del documento formal de la Propuesta de Proyecto de Grado.</li><li>Cronograma de actividades general (WBS y Diagrama de Gantt con ruta crítica).</li><li>Presentación y defensa formal de la propuesta ante jurado examinador.</li><li><strong>Actividad:</strong> <strong>Defensa Oral de la Propuesta y Entrega del 1er Informe de Avance.</strong> (25%)</li></ul><hr><h2 id="✅-resumen-del-trimestre" tabindex="-1">✅ Resumen del Trimestre <a class="header-anchor" href="#✅-resumen-del-trimestre" aria-label="Permalink to &quot;✅ Resumen del Trimestre&quot;">​</a></h2><p>Al finalizar el Trimestre X, los futuros ingenieros cuentan con su propuesta formal aprobada, sus métricas de calidad definidas, el estudio de factibilidad y estimaciones fundamentadas, listos para la fase de diseño arquitectónico y construcción en el Trimestre XI.</p>',19)])])}const p=e(t,[["render",d]]);export{g as __pageData,p as default};
